--[[
通用的奖励格子的逻辑
@params {
    id number  如果是图型卡，卡牌，准备是服务端的id [可选参数]
    dojo table 如果是卡牌CardDojo 图型卡是TarotDojo 装备为EquipDojo [可选参数] （此参数如果存在时则id不能存在）
    goodsId number 为配表goodsId [必需参数]
    isShowNo bool 是否显示普通道具的数量 [可选参数]
    text string 道具自定义显示的文本 [可选参数]
}
]]
------------import------------
local ImageAlterable = CS.Engine.UI.ImageAlterable
local ImageAlterableType = typeof(ImageAlterable)
local StarProgressNode = CS.StarProgressNode
local KTool = CS.Engine.Lib.KTool
local GameUtils = GameUtils
local GoodsUtils = GoodsUtils
local CardConfMgr = CardConfMgr
------------import------------

---@class GoodNodeRectMB
---@field LockNode                        UnityEngine.RectTransform @锁定状态
---@field EquipImg                        UnityEngine.RectTransform @装备或者tarot标识符
---@field CardStar                        UnityEngine.RectTransform @卡牌星级的显示
---@field CardInfo                          UnityEngine.RectTransform @卡牌星级的组的容器
---@field LvOrNoTxt                        UnityEngine.UI.Text @等级或者显示数量的逻辑
---@field LvImg                            UnityEngine.RectTransform @等级lv的文件如果只显示数量的时候这个不显示
---@field LvBg                            UnityEngine.RectTransform @lv等级组容器
---@field CareerImg                        UnityEngine.RectTransform @卡牌职业
---@field CheckImage                        UnityEngine.RectTransform @是否选中的状态
---@field Icon                            UnityEngine.RectTransform @显示的道具图标
---@field TarotPartIcon                    UnityEngine.RectTransform               @图芯卡显示的品质icon
---@field RoleHead                        UnityEngine.RectTransform @卡牌情况下的卡牌头像 两种样式的共有
---@field Text                            UnityEngine.UI.Text @装备中的名称文字
---@field CardNameText                    UnityEngine.UI.Text @卡牌名称，只在长型道具样式下存在
---@field FlagIcon                        UnityEngine.RectTransform @道具类型，只在长型样式下存在
---@field StockNode                        UnityEngine.RectTransform @道具类型，只在长型样式下存在
local GoodNodeRectMB = Class("GoodNodeRectMB")

function GoodNodeRectMB:__init()
    self.params = {}
end

function GoodNodeRectMB:__delete()
    self.params = nil
end

---HiddenAll
---只显示背景状态
function GoodNodeRectMB:HiddenAll()
    KTool.SetActive(self.LockNode.gameObject, false)
    KTool.SetActive(self.EquipImg.gameObject, false)
    KTool.SetActive(self.CardInfo.gameObject, false)
    KTool.SetActive(self.LvBg.gameObject, false)
    KTool.SetActive(self.CheckImage.gameObject, false)
    KTool.SetActive(self.Icon.gameObject, false)

    self:SetSanXingFlagShow(false)
    self:SetSanXingGainShow(false)

end


function GoodNodeRectMB:Awake()
    self:SetSanXingFlagShow(false)
    self:SetSanXingGainShow(false)
end

---Reload
---二次重置刷新节点，特殊需要时调用
------params {
----    id number  如果是图型卡，卡牌，准备是服务端的id [可选参数]
----    dojo table 如果是卡牌CardDojo 图型卡是TarotDojo 装备为EquipDojo [可选参数] （此参数如果存在时则id不能存在）
----    goodsId number 为配表goodsId [必需参数]
----    isShowNo bool 是否显示普通道具的数量 [可选参数]
----    text string 道具自定义显示的文本 [可选参数]
----}
---@param params table
function GoodNodeRectMB:Reload(params)

    KTool.SetActive(self.TarotPartIcon.gameObject, false)
    if not isNull(params) and isTable(params) then
        self.params = params
    end

    if not isSet(self.params, "goodsId") then
        return
    end
    local goodsId = checkNumber(self.params.goodsId)
    if goodsId <= 0 then
        return
    end

    local isShowNo = checkBool(self.params.isShowNo)

    local id = 0
    if isSet(self.params, "dojo") then
        id = checkNumber(self.params.dojo.id)
    elseif isSet(self.params, "id") then
        id = checkNumber(self.params.id)
    end
    local idType = GoodsUtils.GetIdType(goodsId)
    if not isNull(self.FlagIcon) then
        KTool.SetActive(self.FlagIcon.gameObject, true)
        ---表示是长形的通用道具框
        local imageAlterable = self.FlagIcon.gameObject:EnsureComponent(typeof(ImageAlterable))
        if idType == Constants.IDType.Currency then
            --[[        elseif idType == Constants.IDType.CharacterCard then
                        imageAlterable:LoadSprite('uiatlas/common/common_img_role.png')]]
            imageAlterable:LoadSprite("uiatlas/common/common_img_currency.png")
        elseif idType == Constants.IDType.ConsumeGoods then
            imageAlterable:LoadSprite("uiatlas/common/common_img_consume.png")
        else
            imageAlterable:LoadSprite("uiatlas/common/common_img_item.png")
        end
    end
    if (idType == Constants.IDType.CharacterCard) then
        --卡牌
        if not isNull(self.FlagIcon) then
            KTool.SetActive(self.FlagIcon.gameObject, false)
        end
        KTool.SetActive(self.Icon.gameObject, false)
        KTool.SetActive(self.CardInfo.gameObject, true)
        if not isNull(self.StockNode) then
            KTool.SetActive(self.StockNode.gameObject, false)
        end
        self:__FreshCardInfo(id, goodsId)
    elseif (idType == Constants.IDType.EquipArmor or idType == Constants.IDType.EquipWeapon) then
        --KTool.SetActive(self.Icon.gameObject, true)
        --KTool.SetActive(self.CardInfo.gameObject, false)
        --self:__FreshEquipGoodInfo(id, goodsId)
    elseif
        idType == Constants.IDType.Equipment then
        --tarot
        KTool.SetActive(self.Icon.gameObject, true)
        KTool.SetActive(self.CardInfo.gameObject, false)
        self:__FreshTarotInfo(id, goodsId)
    else
        KTool.SetActive(self.Icon.gameObject, true)
        KTool.SetActive(self.CardInfo.gameObject, false)
        --普通道具才是id否则需要从玩家信息中获取
        self:__FreshCommonGoodInfo(goodsId, isShowNo, self.params.text)
    end
end

---__FreshCardInfo
---刷新卡牌的样式
---@param id number 卡牌的数据库id
---@param goodsId number 卡牌的配表id
function GoodNodeRectMB:__FreshCardInfo(id, goodsId)
    --显示卡牌属性相关信息容器

    if self.FlagIcon then
        KTool.SetActive(self.FlagIcon.gameObject, false)
    end

    if self.CardInfo then
        KTool.SetActive(self.CardInfo.gameObject, true)
    end

    local hasDojo = isSet(self.params, "dojo")
    local cardDojo = nil

    if hasDojo then
        cardDojo = self.params.dojo
    elseif checkNumber(id) > 0 then
        ---@type CardComponent
        local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
        ---@type CardDojo
        cardDojo = cardComponent:GetCardById(id)
    end
    local cardId = checkNumber(goodsId)
    ---@type CardConfMgr
    local cardConfMgr = CardConfMgr:GetInstance()
    local cardVo = cardConfMgr:GetCardByRefId(cardId)
    if cardVo == nil then
        return
    end
    ---如果是卡牌
    local cardVo = CardConfMgr:GetInstance():GetCardByRefId(goodsId) ---然后取初始的皮肤 然后取头像等
    ---@type CardSkinVo
    local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(cardVo.defaultSkin)
    self.RoleHead.gameObject:EnsureComponent(ImageAlterableType):LoadSprite(skinVo.buffHead)
    if not isNull(self.CardNameText) then
        ---是长形的通用道具条
        self.CardNameText.text = tostring(cardVo.name)
        self.RoleHead:SetScaleXY(0.58, 0.58)
        --- @type UnityEngine.GameObject
        self.controller.gameObject:EnsureComponent(ImageAlterableType):LoadSprite(GoodsUtils.GetGoodsBackgroundByQualityType(cardVo.rare, true, true))
    else
        --- @type UnityEngine.GameObject
        self.controller.gameObject:EnsureComponent(ImageAlterableType):LoadSprite(GoodsUtils.GetGoodsBackgroundByQualityType(cardVo.rare, false, true))
    end

    --属性更新
    --self.AttrImg.gameObject:EnsureComponent(ImageAlterableType):LoadSprite(CardUtils.GetGoodsCardAttrIconByCardAttrType(cardVo.attributeType))
    self.CareerImg.gameObject:EnsureComponent(ImageAlterableType):LoadSprite(cardConfMgr:GetCardCareerIconByType(cardVo.career))
    if isTable(cardDojo) then
        if not isNull(self.FlagIcon) then
            ---存在卡牌等级等信息时不显示类别
            KTool.SetActive(self.FlagIcon.gameObject, false)
        end
        --如果存在服务端对照的卡牌数据时
        --- @type UnityEngine.RectTransform
        self.CardStar.gameObject:GetComponent(typeof(StarProgressNode)):SetStarNo(Constants.CardMaxStar, checkNumber(cardDojo.star))
        --- @type UnityEngine.RectTransform
        KTool.SetActive(self.LvBg.gameObject, true)
        --- @type UnityEngine.RectTransform
        KTool.SetActive(self.LvImg.gameObject, true and not GameUtils.GetChannelId() == Config.CHANNEL_REVIEW)
        --- @type UnityEngine.UI.Text
        self.LvOrNoTxt.text = tostring(cardDojo.cardLevel)
    else
        self.CardStar.gameObject:GetComponent(typeof(StarProgressNode)):SetStarNo(Constants.CardMaxStar, 0)
        KTool.SetActive(self.LvImg.gameObject, false)
        if not isNull(self.params.text) then
            KTool.SetActive(self.LvBg.gameObject, true)
            --- @type UnityEngine.UI.Text
            self.LvOrNoTxt.text = checkString(self.params.text)
        else
            --- @type UnityEngine.RectTransform
            KTool.SetActive(self.LvBg.gameObject, false)
        end
    end
end

