---__FreshTarotInfo 私有方法
---刷新图型卡的样式
---@param id number 图型卡的数据库id
---@param goodsId number 图型卡的配表id
function GoodNodeRectMB:__FreshTarotInfo(id, goodsId)
    KTool.SetActive(self.CardInfo.gameObject, false)
    if not isNull(self.StockNode) then
        KTool.SetActive(self.StockNode.gameObject, false)
    end
    --- @type UnityEngine.RectTransform
    KTool.SetActive(self.LvBg.gameObject, true)

    local hasDojo = isSet(self.params, "dojo")
    local equipDojo = nil
    if hasDojo then
        equipDojo = self.params.dojo
    else
        if checkNumber(id) > 0 then
            --可能会存在外部不存在id的情况这时就只显示一个空图标
            ---@type EquipmentComponent
            local equipComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.EquipmentComponent)
            ---@type EquipDojo
            equipDojo = equipComponent:GetEquipById(id)
        end
    end
    local tarotRefId = checkNumber(goodsId)
    ---@type CardConfMgr
    local cardConfMgr = CardConfMgr:GetInstance()
    local tarotVo = cardConfMgr:GetTarotByRefId(tarotRefId)
    if isTable(tarotVo) then
        ---如果是狗粮与图芯卡要区别开
        KTool.SetActive(self.TarotPartIcon.gameObject, checkInt(tarotVo.tarotType) ~= Constants.TarotType.DogFood)
        --- @type UnityEngine.RectTransform
        self.Icon.gameObject:GetComponent(ImageAlterableType):LoadSprite(tarotVo.iconPath)
        if checkInt(tarotVo.tarotType) == Constants.TarotType.Chip then
            --图芯卡
            self.TarotPartIcon.gameObject:EnsureComponent(ImageAlterableType):LoadSprite(string.format("uiatlas/common/tarot_bg_%d_%d.png", checkInt(tarotVo.part), checkInt(tarotVo.quality)))
        end
        self.Icon:SetScaleXY(0.8, 0.8)

        if isTable(equipDojo) then
            --如果存在服务端对照的tarot数据时
            --- @type UnityEngine.RectTransform
            KTool.SetActive(self.LvImg.gameObject, true and not GameUtils.GetChannelId() == Config.CHANNEL_REVIEW)
            --- @type UnityEngine.UI.Text
            self.LvOrNoTxt.text = equipDojo.level
        else
            KTool.SetActive(self.LvImg.gameObject, false)
            if not isNull(self.params.text) then
                KTool.SetActive(self.LvBg.gameObject, true)
                --- @type UnityEngine.UI.Text
                self.LvOrNoTxt.text = checkString(self.params.text)
            else
                --- @type UnityEngine.RectTransform
                KTool.SetActive(self.LvBg.gameObject, false)
            end
        end
    else
        print(tarotRefId)
    end
end

---ShowStock
---显示库存
function GoodNodeRectMB:ShowStock()
    if not isNull(self.StockNode) then
        KTool.SetActive(self.StockNode.gameObject, true)
    end
end

---__FreshCommonGoodInfo 私有方法
---刷新普通道具的样式
---@param goodsId number 道具id
---@param isShowNo boolean 是否显示普通道具的数量
---@param text string 道具自定义显示的文本
function GoodNodeRectMB:__FreshCommonGoodInfo(goodsId, isShowNo, text)
    --self.Icon:SetScaleXY(0.8, 0.8)
    ---@type GoodsConfMgr
    local goodsConfMgr = GoodsConfMgr:GetInstance()
    local vo = goodsConfMgr:GetGoodsVoById(goodsId)
    if vo == nil then
        return
    end
    KTool.SetActive(self.CardInfo.gameObject, false)
    --- @type UnityEngine.RectTransform
    KTool.SetActive(self.EquipImg.gameObject, checkBool(isShowNo))
    KTool.SetActive(self.LvBg.gameObject, false)

    --- @type UnityEngine.RectTransform
    self.Icon.gameObject:EnsureComponent(ImageAlterableType):LoadSprite(vo.photoPath)
    if not isNull(self.FlagIcon) then
        --- @type UnityEngine.GameObject
        self.controller.gameObject:EnsureComponent(ImageAlterableType):LoadSprite(GoodsUtils.GetGoodsBackgroundByQualityType(vo.quality, true))
    else
        ----- @type UnityEngine.UI.Text
        --self.LvOrNoTxt.text = checkString(text)
        --- @type UnityEngine.GameObject
        self.controller.gameObject:EnsureComponent(ImageAlterableType):LoadSprite(GoodsUtils.GetGoodsBackgroundByQualityType(vo.quality))
        if true == checkBool(isShowNo) and text == nil then
            text = GoodsUtils.GetThingNo(goodsId)
        end
        self.Text.text = tostring(text)
    end
end

---SetCheckState
---调置goodNode的是否选中状态
---@param isChecked boolean 是否选中状态
function GoodNodeRectMB:SetCheckState(isChecked)
    --- @type UnityEngine.RectTransform
    KTool.SetActive(self.CheckImage.gameObject, checkBool(isChecked))
end

---SetEquipState
---设置是否在装备中的状态
---@param isShow boolean 是否显示装备状态
function GoodNodeRectMB:SetEquipState(isShow)
    KTool.SetActive(self.EquipImg.gameObject, checkBool(isShow))
    self.Text.text = localize("装备中")
end

---SetEquipState
---设置是否锁定的状态
---@param isShow boolean 是否锁定的状态
function GoodNodeRectMB:SetLockState(isShow)
    KTool.SetActive(self.LockNode.gameObject, checkBool(isShow))
end

---GetLvNo
---获取道具当前显示的数量
---
function GoodNodeRectMB:GetLvNo()
    local num = self.LvOrNoTxt.text
    return checkNumber(num)
end


function GoodNodeRectMB:OnDestroy()
    self.controller = nil
     --luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

function GoodNodeRectMB:SetShow(isshow)
    KTool.SetActive(self.controller.gameObject, isshow)
end

-- 增加三星奖励的标签
function GoodNodeRectMB:SetSanXingFlagShow(isshow)
   KTool.SetActive(self.sanxingbonus,isshow)
end

-- 增加三星奖励的已获得
function GoodNodeRectMB:SetSanXingGainShow(isshow)
   KTool.SetActive(self.sanxinggetimg,isshow)
end    



return GoodNodeRectMB
